sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
	if (isLoading || newValue === '') {
		return;
	}

	ScriptLoader.getScripts('CustomUtils.jsdbx', function() {

		g_form.getReference('caller_id', function(caller) {
			var userIdName = 'u_user_id';
			var isDisabled = CustomUtils.ToBoolean(caller.getValue('vip'));

			g_form.setReadOnly(userIdName, isDisabled);
			g_form.setValue(userIdName, caller.getValue('user_name'));
		});

	});

}
